const { createApp, ref, computed, watch, onMounted, onBeforeUnmount } = Vue;
const TATUI = [-23.3556, -47.8561];

const money = (value, tipo = '') => `${Number(value || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}${tipo === 'Aluguel' ? '/mês' : ''}`;
const params = () => new URLSearchParams(location.search);

const Header = {
  props: { usuario: Object },
  emits: ['logout'],
  setup(props) { const aberto = ref(false); const primeiroNome = computed(() => String(props.usuario?.nome || '').trim().split(/\s+/).filter(Boolean)[0] || 'usuário'); const iniciais = computed(() => String(props.usuario?.nome || '').trim().split(/\s+/).filter(Boolean).slice(0, 2).map(nome => nome[0].toUpperCase()).join('') || 'US'); const alternar = () => { aberto.value = !aberto.value; }; const sair = () => { aberto.value = false; }; return { aberto, primeiroNome, iniciais, alternar, sair }; },
  template: `<header class="react-header"><a class="react-brand" href="index.html"><img src="assets/tatui-imoveis-logo.svg" alt="Tatuí Imóveis — O portal de imóveis de Tatuí"></a><a class="home-button" href="index.html">Página inicial</a><nav class="react-nav"><a href="imoveis.html" :class="{active: locationPath.includes('imoveis') || locationPath.includes('imovel.html')}">Imóveis</a><a href="cadastro.html">Anunciar</a><template v-if="usuario"><div class="react-user-menu"><button class="react-user-link" type="button" @click="alternar" :aria-expanded="aberto"><span class="react-avatar">{{ iniciais }}</span><span class="react-greeting">Olá, {{ primeiroNome }}</span><span class="user-chevron">⌄</span></button><div v-if="aberto" class="user-dropdown"><a href="perfil.html">Meu perfil</a><a href="perfil.html#seus-imoveis">Meus imóveis</a><button type="button" @click="sair(); $emit('logout')">Sair</button></div></div></template><a v-else class="react-action" href="login.html">Área do usuário</a></nav></header>`,
  computed: { locationPath: () => location.pathname }
};

const Footer = { template: `<footer class="site-footer"><a class="site-footer-brand" href="index.html"><img src="assets/tatui-imoveis-logo-light.svg" alt="Tatuí Imóveis"><span>O portal de imóveis de Tatuí.</span></a><nav><a href="imoveis.html">Comprar</a><a href="imoveis.html?tipo=Aluguel">Alugar</a><a href="imoveis.html">Imóveis</a><a href="index.html#contato">Contato</a></nav><span class="site-footer-note">Tatuí, a cidade que a gente ama.</span></footer>` };

const Layout = {
  components: { Header, Footer },
  props: { eyebrow: String, usuario: Object },
  emits: ['logout'],
  template: `<div class="react-shell"><Header :usuario="usuario" @logout="$emit('logout')"/><main class="react-page"><p class="eyebrow">{{ eyebrow }}</p><slot></slot></main><Footer/></div>`
};

const PropertyCard = { props: { item: Object }, setup(props) { const fotoAtual = ref(0); const anterior = event => { event.stopPropagation(); fotoAtual.value = fotoAtual.value > 0 ? fotoAtual.value - 1 : props.item.fotos.length - 1; }; const proxima = event => { event.stopPropagation(); fotoAtual.value = (fotoAtual.value + 1) % props.item.fotos.length; }; return { fotoAtual, anterior, proxima }; }, template: `<article class="listing-property-card"><div class="listing-property-image"><a class="listing-property-image-link" :href="'imovel.html?id=' + item.id"><img v-if="item.fotos?.[fotoAtual]" :src="item.fotos[fotoAtual].url" :alt="item.fotos[fotoAtual].nome || item.titulo"><span v-else>Sem foto disponível</span></a><template v-if="item.fotos?.length > 1"><button type="button" class="listing-photo-arrow listing-photo-prev" aria-label="Foto anterior" @click="anterior">‹</button><button type="button" class="listing-photo-arrow listing-photo-next" aria-label="Próxima foto" @click="proxima">›</button><div class="listing-photo-dots"><i v-for="(_, index) in item.fotos" :key="index" :class="{ active: index === fotoAtual }"></i></div></template></div><div class="listing-property-body"><a class="listing-property-main" :href="'imovel.html?id=' + item.id"><span class="listing-property-type">{{ item.tipo }} · {{ item.categoria }}</span><h2>{{ item.titulo }}</h2><strong class="listing-property-price">{{ money(item.preco, item.tipo) }}</strong><p class="listing-property-address">{{ item.endereco }}</p><p class="listing-property-description">{{ item.descricao || 'Confira todos os detalhes deste imóvel.' }}</p></a><div class="listing-property-footer"><span>Publicado no Tatuí Imóveis</span><a :href="'imovel.html?id=' + item.id">Ver detalhes →</a></div></div></article>`, methods: { money } };

PropertyCard.props.showEdit = { type: Boolean, default: false };
PropertyCard.template = PropertyCard.template.replace('Ver detalhes →</a>', 'Ver detalhes →</a><a v-if="showEdit" class="listing-edit-link" :href="\'cadastro.html?modo=editar&id=\' + item.id">Editar imóvel</a>');

const Home = {
  components: { Header },
  setup() {
    const usuario = ref(null); const imoveis = ref([]); const query = ref(''); const negociacao = ref(''); const tipo = ref(''); const preco = ref(''); const suggestions = ref([]); const error = ref(''); const mapEl = ref(null); let map; let layer; let timer;
    const categorias = [['Casa', 'icon-casa.svg'], ['Apartamento', 'icon-apartamento.svg'], ['Terreno', 'icon-terreno.svg'], ['Chácara / Sítio', 'icon-chacara.svg'], ['Comercial', 'icon-comercial.svg']];
    const logout = async () => { await fetch('/api/logout', { method: 'POST' }); usuario.value = null; };
    const carregar = async () => { const [conta, lista] = await Promise.all([fetch('/api/minha-conta').then(r => r.ok ? r.json() : null), fetch('/api/imoveis').then(r => r.json())]); usuario.value = conta?.usuario || null; imoveis.value = Array.isArray(lista) ? lista : []; };
    const popup = item => { const foto = item.fotos?.[0]; const detailUrl = `imovel.html?id=${item.id}`; return `<article class="react-popup">${foto ? `<a class="react-popup-image-link" href="${detailUrl}" aria-label="Ver detalhes de ${item.titulo}"><img class="react-popup-image" src="${foto.url}" alt="${foto.nome || item.titulo}"></a>` : ''}<small>${item.tipo}</small><h3>${item.titulo}</h3><p>${money(item.preco, item.tipo)}</p><a href="${detailUrl}">Ver detalhes</a></article>`; };
    const desenharMarcadores = () => { if (!layer) return; layer.clearLayers(); imoveis.value.forEach(item => { const c = item.coordenadas || {}; if (!c.latitude || !c.longitude) return; const marker = L.marker([c.latitude, c.longitude]).addTo(layer); marker.on('click', () => map.setView([c.latitude, c.longitude], map.getZoom(), { animate: false })); marker.bindPopup(popup(item), { autoPan: false, maxWidth: 290, minWidth: 210 }); marker.on('popupopen', () => { setTimeout(() => { const markerPoint = map.latLngToContainerPoint(marker.getLatLng()); const targetPoint = L.point(map.getSize().x / 2, map.getSize().y * 0.82); map.panBy(markerPoint.subtract(targetPoint), { animate: true, duration: 0.25 }); }, 30); }); }); };
    const geocodificar = async value => { const url = `https://api.mapbox.com/geocoding/v5/mapbox.places/${encodeURIComponent(`${value}, Tatuí, SP`)}.json?access_token=${MAPBOX_TOKEN}&language=pt-BR&country=br&limit=5&autocomplete=true&types=address,postcode,neighborhood,locality,place`; const data = await fetch(url).then(r => r.json()); return data.features || []; };
    const sugerir = () => { clearTimeout(timer); if (query.value.trim().length < 3) { suggestions.value = []; return; } timer = setTimeout(async () => { suggestions.value = await geocodificar(query.value); }, 350); };
    const buscar = async () => { const p = new URLSearchParams(); if (query.value.trim()) p.set('q', query.value.trim()); if (negociacao.value) p.set('tipo', negociacao.value); if (tipo.value) p.set('categoria', tipo.value); if (preco.value) p.set('faixa', preco.value); if (query.value.trim().length >= 3) { error.value = 'Buscando localização…'; try { const features = await geocodificar(query.value); if (features[0] && map) map.setView([features[0].center[1], features[0].center[0]], 15); } catch (_) { error.value = ''; } } location.href = `imoveis.html${p.toString() ? `?${p}` : ''}`; };
    const selecionar = feature => { query.value = feature.place_name; suggestions.value = []; if (map) map.setView([feature.center[1], feature.center[0]], 15); };
    onMounted(async () => { await carregar(); map = L.map(mapEl.value, { zoomControl: true }).setView(TATUI, 13); L.tileLayer(`https://api.mapbox.com/styles/v1/mapbox/streets-v12/tiles/{z}/{x}/{y}?access_token=${MAPBOX_TOKEN}`, { attribution: '&copy; Mapbox &copy; OpenStreetMap', tileSize: 512, zoomOffset: -1, maxZoom: 19 }).addTo(map); layer = L.layerGroup().addTo(map); desenharMarcadores(); setTimeout(() => map.invalidateSize(), 100); });
    return { usuario, imoveis, query, negociacao, tipo, preco, suggestions, error, categorias, mapEl, sugerir, buscar, selecionar, logout };
  },
  template: `<div class="home-redesign"><Header :usuario="usuario" @logout="logout"/><section class="home-hero"><div class="home-hero-content"><p class="home-kicker">Tatuí, a cidade para chamar de lar</p><h1>Encontre seu lugar em Tatuí.</h1><p>Casas, apartamentos, terrenos, chácaras e imóveis comerciais para comprar ou alugar.</p></div><form class="home-search" @submit.prevent="buscar"><label class="home-location-field"><span>⌖</span><input v-model="query" @input="sugerir" placeholder="Digite bairro, região ou palavra-chave" autocomplete="off"></label><select v-model="negociacao" aria-label="Negociação"><option value="">Comprar ou alugar</option><option value="Venda">Comprar</option><option value="Aluguel">Alugar</option></select><select v-model="tipo" aria-label="Tipo de imóvel"><option value="">Tipo de imóvel</option><option>Casa</option><option>Apartamento</option><option>Terreno</option><option>Chácara / Sítio</option><option>Comercial</option></select><select v-model="preco" aria-label="Faixa de preço"><option value="">Faixa de preço</option><option value="ate-250000">Até R$ 250 mil</option><option value="250000-500000">R$ 250 a 500 mil</option><option value="acima-500000">Acima de R$ 500 mil</option></select><button type="submit">⌕&nbsp; Buscar imóveis</button><div v-if="suggestions.length" class="home-suggestions"><button v-for="item in suggestions" type="button" :key="item.id" @click="selecionar(item)">{{ item.place_name }}</button></div><small v-if="error" class="home-search-error">{{ error }}</small></form></section><section class="home-map-section" id="mapa"><div class="home-map-column"><div class="home-section-copy"><p class="home-kicker">Explore Tatuí</p><h2>Imóveis no mapa</h2><p>Veja os imóveis disponíveis em Tatuí e encontre o seu próximo endereço.</p><a href="imoveis.html">Ver todos os imóveis →</a></div><div class="home-map"><div ref="mapEl" id="vue-map"></div><span>Arraste o mapa para explorar</span></div></div><aside class="home-announce-card"><p class="home-kicker">Tem um imóvel em Tatuí?</p><h2>Anuncie seu imóvel grátis.</h2><p>É rápido, simples e sem custo. Seu imóvel pode estar à procura de um novo dono ou inquilino agora mesmo.</p><a class="home-announce-button" href="cadastro.html">Anunciar agora grátis&nbsp; →</a></aside></section><section class="home-categories"><div><p class="home-kicker">Encontre com facilidade</p><h2>Busque por categoria</h2><p>Escolha o tipo de imóvel ideal para você.</p></div><div class="home-category-grid"><a v-for="([label, icon]) in categorias" :key="label" :href="'imoveis.html?categoria=' + encodeURIComponent(label)"><strong :style="{backgroundImage: 'url(assets/' + icon + ')'}"></strong><span>{{ label }}</span></a></div></section><footer class="home-footer" id="contato"><a class="home-logo" href="/"><span class="home-logo-mark">⌂</span><span><strong>TATUÍ IMÓVEIS</strong><small>O portal de imóveis de Tatuí.</small></span></a><span>© Tatuí Imóveis</span><span>Foto: Santuário Conceição / Wikimedia Commons (CC BY-SA 4.0)</span></footer></div>`
};

const Listing = { components: { Layout, PropertyCard }, setup() { const usuario = ref(null); const all = ref(null); const p = params(); const filters = ref({ q: p.get('q') || '', categoria: p.get('categoria') || '', tipo: p.get('tipo') || '', faixa: p.get('faixa') || '' }); const carregar = async () => { const [conta, lista] = await Promise.all([fetch('/api/minha-conta').then(r => r.ok ? r.json() : null), fetch('/api/imoveis').then(r => r.json())]); usuario.value = conta?.usuario || null; all.value = lista; }; const filtered = computed(() => (all.value || []).filter(item => { const ids = p.get('ids'); const q = filters.value.q.toLowerCase(); if (ids && !ids.split(',').includes(String(item.id))) return false; if (filters.value.categoria && String(item.categoria || '').toLowerCase() !== filters.value.categoria.toLowerCase()) return false; if (filters.value.tipo && String(item.tipo || '').toLowerCase() !== filters.value.tipo.toLowerCase()) return false; if (q && ![item.titulo, item.endereco, item.descricao, item.categoria].some(v => String(v || '').toLowerCase().includes(q))) return false; const price = Number(item.preco || 0); if (filters.value.faixa === 'ate-250000' && price > 250000) return false; if (filters.value.faixa === '250000-500000' && (price < 250000 || price > 500000)) return false; if (filters.value.faixa === 'acima-500000' && price <= 500000) return false; return true; })); const atualizar = () => { const next = new URLSearchParams(); Object.entries(filters.value).forEach(([k, v]) => v && next.set(k, v)); history.replaceState(null, '', `imoveis.html?${next}`); }; const logout = async () => { await fetch('/api/logout', { method: 'POST' }); usuario.value = null; }; const titulo = computed(() => filters.value.tipo === 'Venda' ? 'Imóveis à venda em Tatuí' : filters.value.tipo === 'Aluguel' ? 'Imóveis para alugar em Tatuí' : filters.value.categoria ? `${filters.value.categoria} em Tatuí` : 'Imóveis em Tatuí'); onMounted(carregar); return { usuario, all, filters, filtered, titulo, atualizar, logout, money }; }, template: `<Layout :usuario="usuario" eyebrow="Encontre seu imóvel" @logout="logout"><div class="listing-heading"><div><h1>{{ titulo }}</h1><p class="react-lead">Encontre seu próximo endereço com anúncios publicados no Tatuí Imóveis.</p></div><a class="react-button" href="cadastro.html">Anunciar imóvel</a></div><form class="listing-top-search" @submit.prevent="atualizar"><span class="listing-search-icon">⌕</span><input v-model="filters.q" aria-label="Buscar imóveis" placeholder="Digite bairro, região ou palavra-chave"><select v-model="filters.tipo" aria-label="Negociação"><option value="">Comprar ou alugar</option><option value="Venda">Comprar</option><option value="Aluguel">Alugar</option></select><select v-model="filters.categoria" aria-label="Tipo de imóvel"><option value="">Tipo de imóvel</option><option>Casa</option><option>Apartamento</option><option>Terreno</option><option>Chácara / Sítio</option><option>Comercial</option></select><select v-model="filters.faixa" aria-label="Faixa de preço"><option value="">Faixa de preço</option><option value="ate-250000">Até R$ 250 mil</option><option value="250000-500000">R$ 250 a 500 mil</option><option value="acima-500000">Acima de R$ 500 mil</option></select><button type="submit">Buscar imóveis</button></form><div class="listing-layout"><aside class="listing-filters"><strong>Filtre sua busca</strong><p class="react-lead">Use a barra acima para refinar os resultados.</p><a class="react-button secondary" href="imoveis.html">Limpar filtros</a></aside><section class="listing-results"><div class="listing-results-bar"><strong>{{ all === null ? 'Carregando…' : filtered.length + (filtered.length === 1 ? ' imóvel encontrado' : ' imóveis encontrados') }}</strong><label>Ordenar<select><option>Mais recentes</option></select></label></div><div class="react-property-grid"><p v-if="all === null">Carregando imóveis…</p><p v-else-if="!filtered.length" class="listing-empty"><strong>Nenhum imóvel encontrado</strong><br>Tente remover algum filtro ou fazer uma nova busca.</p><PropertyCard v-else v-for="item in filtered" :key="item.id" :item="item"/></div></section></div></Layout>` };

const Detail = {
  components: { Layout },
  setup() {
    const usuario = ref(null); const item = ref(null); const contact = ref(false); const message = ref(''); const lightboxIndex = ref(null);
    const carregar = async () => { const id = Number(params().get('id')); const [conta, lista] = await Promise.all([fetch('/api/minha-conta').then(r => r.ok ? r.json() : null), fetch('/api/imoveis').then(r => r.json())]); usuario.value = conta?.usuario || null; item.value = lista.find(x => x.id === id) || false; };
    const enviar = async event => { const response = await fetch(`/api/imoveis/${item.value.id}/contatos`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(new FormData(event.target))) }); const result = await response.json(); message.value = result.message || result.error; if (response.ok) event.target.reset(); };
    const abrirGaleria = index => { lightboxIndex.value = index; };
    const fecharGaleria = () => { lightboxIndex.value = null; };
    const proximaFoto = () => { if (item.value?.fotos?.length) lightboxIndex.value = (lightboxIndex.value + 1) % item.value.fotos.length; };
    const fotoAnterior = () => { if (item.value?.fotos?.length) lightboxIndex.value = (lightboxIndex.value - 1 + item.value.fotos.length) % item.value.fotos.length; };
    const atalhosGaleria = event => { if (lightboxIndex.value === null) return; if (event.key === 'Escape') fecharGaleria(); if (event.key === 'ArrowRight') proximaFoto(); if (event.key === 'ArrowLeft') fotoAnterior(); };
    const logout = async () => { await fetch('/api/logout', { method: 'POST' }); usuario.value = null; };
    onMounted(() => { carregar(); window.addEventListener('keydown', atalhosGaleria); });
    onBeforeUnmount(() => window.removeEventListener('keydown', atalhosGaleria));
    return { usuario, item, contact, message, lightboxIndex, enviar, abrirGaleria, fecharGaleria, proximaFoto, fotoAnterior, logout, money };
  },
  template: `<Layout :usuario="usuario" :eyebrow="item ? item.tipo + ' · ' + item.categoria : 'Detalhes do imóvel'" @logout="logout"><p v-if="item === null">Carregando imóvel…</p><template v-else-if="!item"><h1>Imóvel não encontrado.</h1><a href="imoveis.html">Voltar para a lista</a></template><template v-else><h1>{{ item.titulo }}</h1><div v-if="item.fotos?.length" class="property-gallery"><button v-for="(foto, index) in item.fotos" :key="foto.id" type="button" class="property-gallery-item" @click="abrirGaleria(index)"><img :src="foto.url" :alt="foto.nome || item.titulo"><span>Ampliar foto {{ index + 1 }}</span></button></div><p class="property-gallery-hint" v-if="item.fotos?.length">Clique em uma foto para ampliar e navegar pela galeria.</p><p class="react-price">{{ money(item.preco, item.tipo) }}</p><p class="react-lead">⌖ {{ item.endereco }}</p><p class="react-description">{{ item.descricao }}</p><div class="property-detail-actions"><button class="react-button" @click="contact = true">Entrar em contato</button><a v-if="usuario?.usuario?.id === item.usuario_id" class="react-button secondary" :href="'cadastro.html?modo=editar&id=' + item.id">Editar imóvel</a></div><div v-if="lightboxIndex !== null" class="property-lightbox" role="dialog" aria-modal="true" aria-label="Galeria de fotos" @click.self="fecharGaleria"><button type="button" class="lightbox-close" aria-label="Fechar galeria" @click="fecharGaleria">×</button><button v-if="item.fotos.length > 1" type="button" class="lightbox-nav lightbox-prev" aria-label="Foto anterior" @click="fotoAnterior">‹</button><figure class="lightbox-content"><img :src="item.fotos[lightboxIndex].url" :alt="item.fotos[lightboxIndex].nome || item.titulo"><figcaption>Foto {{ lightboxIndex + 1 }} de {{ item.fotos.length }}</figcaption></figure><button v-if="item.fotos.length > 1" type="button" class="lightbox-nav lightbox-next" aria-label="Próxima foto" @click="proximaFoto">›</button><div v-if="item.fotos.length > 1" class="lightbox-thumbnails"><button v-for="(foto, index) in item.fotos" :key="foto.id" type="button" :class="{ active: index === lightboxIndex }" :aria-label="'Ver foto ' + (index + 1)" @click="abrirGaleria(index)"><img :src="foto.url" :alt="foto.nome || item.titulo"></button></div></div><div v-if="contact" class="react-modal"><div class="react-modal-card"><button class="modal-close" @click="contact = false">×</button><h2>Entrar em contato</h2><form class="react-form" @submit.prevent="enviar"><label>Nome<input name="nome" required></label><label>Telefone<input name="telefone" required></label><label>E-mail<input name="email" type="email" required></label><p v-if="message">{{ message }}</p><button class="react-button">Enviar contato</button></form></div></div></template></Layout>`
};

const Login = { components: { Layout }, setup() { const email = ref(''); const senha = ref(''); const data = ref(null); const message = ref(''); const carregar = () => fetch('/api/minha-conta').then(r => r.ok ? r.json() : null).then(v => data.value = v); const submit = async () => { message.value = 'Entrando…'; const r = await fetch('/api/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: email.value, senha: senha.value }) }); const result = await r.json(); if (!r.ok) message.value = result.error || 'Não foi possível entrar.'; else location.href = 'meus-imoveis.html'; }; const logout = async () => { await fetch('/api/logout', { method: 'POST' }); data.value = null; }; onMounted(carregar); return { email, senha, data, message, submit, logout }; }, template: `<Layout eyebrow="Acesso do usuário" :usuario="data?.usuario" @logout="logout"><template v-if="data"><h1>Olá, {{ data.usuario.nome }}.</h1><p class="react-lead">Você já está conectado.</p><a class="react-button" href="meus-imoveis.html">Ver meus imóveis</a></template><template v-else><h1>Entre na sua conta.</h1><p class="react-lead">Acesse os imóveis cadastrados por você.</p><form class="react-form" @submit.prevent="submit"><label>E-mail<input type="email" v-model="email" required></label><label>Senha<input type="password" v-model="senha" required></label><p v-if="message" class="react-error">{{ message }}</p><button class="react-button">Entrar</button></form><p class="react-lead">Ainda não tem cadastro? <a href="cadastro.html">Cadastre um imóvel</a>.</p></template></Layout>` };

